// references it) or its dlopen fails. Provenance: the EGL_ANDROID_
// presentation_time extension spec. No GPL-3.0 sources.
__attribute__((visibility("default"))) unsigned int
eglPresentationTimeANDROID(void* dpy, void* sur, long long time) {
  (void)dpy;
  (void)sur;
  (void)time;
  return 1u;  // EGL_TRUE
}

// eglDupNativeFenceFDANDROID: EGL_ANDROID_native_fence_sync — dup a sync's
